"""Original, deterministic synthetic municipal project dossiers for the speed matrix.

These are workload fixtures, not evidence about real people or municipalities.
The dossier combines different document types and project-specific constraints;
its repeating report structure is intentional and is recorded in the manifest.
"""
from __future__ import annotations

# Each project supplies a different operational question, constraint and observation.
# German and English describe the same synthetic portfolio independently of token length.
